import numpy as np

class GridWorld:
    def __init__(self, size=4):
        self.size = size
        self.n_states = size * size
        self.n_actions = 4
        self.goal = size * size - 1

    def step(self, state, action):
        x, y = state // self.size, state % self.size
        if action == 0: x = max(0, x-1)
        elif action == 1: x = min(self.size-1, x+1)
        elif action == 2: y = max(0, y-1)
        elif action == 3: y = min(self.size-1, y+1)
        next_s = x * self.size + y
        reward = 1.0 if next_s == self.goal else -0.01
        done = next_s == self.goal
        return next_s, reward, done

    def reset(self):
        return 0
```

